public static void hydrateAggregatorsFromCache(
    final List<AggregatorFactory> aggregators,
    final Iterator<Object> resultIter,
    final boolean isResultLevelCache,
    final CacheStrategy.AddToResultFunction addToResultFunction
)
{
  sharedSupport().hydrateAggregators(aggregators, resultIter, isResultLevelCache, addToResultFunction);
}

private void hydrateAggregators(
    final List<AggregatorFactory> aggregators,
    final Iterator<Object> resultIter,
    final boolean isResultLevelCache,
    final CacheStrategy.AddToResultFunction addToResultFunction
)
{
  cacheAggResultLevelHolder.set(Boolean.valueOf(isResultLevelCache));
  if (aggregators == null) {
    return;
  }
  for (int i = 0; i < aggregators.size(); i++) {
    final AggregatorFactory aggregator = aggregators.get(i);
    cacheAggFactoryHolder.set(aggregator);
    cacheAggIndexHolder.set(Integer.valueOf(i));
    if (!resultIter.hasNext()) {
      throw new ISE("Ran out of objects while reading aggregators from cache!");
    }
    final Object raw = resultIter.next();
    inspectCacheAggValue(raw);
    if (isResultLevelCache) {
      addToResultFunction.apply(aggregator.getName(), i, raw);
    } else {
      addToResultFunction.apply(aggregator.getName(), i, aggregator.deserialize(raw));
    }
  }
}

