      addToResultFunction.apply(aggregator.getName(), i, aggregator.deserialize(raw));
    }
  }
}

public static ResultRow convertLegacyRow(final Row row, final GroupByQuery query)
{
  return sharedSupport().convertLegacyRowInternal(row, query);
